set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000006","session_id":"00000000-0000-0000-0000-000000000006"}',true);
select public.review_test_relationship('00000000-0000-0000-0000-000000000004','00000000-0000-0000-0000-000000000001',1,'approved','Independent synthetic adult test relationship.',gen_random_uuid());
create temporary table consent_intent as select (public.load_test_trust_workspace()#>>'{relationships,0,consent_event}')::bigint event;
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000004","session_id":"00000000-0000-0000-0000-000000000004"}',true);
select pg_temp.assert_true((select count(*)=0 from public.lesson_progress),'approved link alone grants no access');
select pg_temp.expect_error($q$select public.review_test_relationship(auth.uid(),'00000000-0000-0000-0000-000000000002',0,'approved','Guardian cannot create their own link.',gen_random_uuid())$q$,'42501','guardian cannot self-establish relationship');
select public.record_test_consent('10000000-0000-0000-0000-000000000001',(select event from consent_intent),true,'Explicit adult-test consent for the classroom.','82000000-0000-4000-8000-000000000001');
select public.record_test_consent('10000000-0000-0000-0000-000000000001',(select event from consent_intent),true,'Explicit adult-test consent for the classroom.','82000000-0000-4000-8000-000000000001');
select pg_temp.assert_true((select count(*)=1 from public.lesson_progress),'test consent permits only linked learner progress');
select pg_temp.assert_true(public.read_linked_test_learner('10000000-0000-0000-0000-000000000001')->>'test_only'='true','linked learner RPC is labelled test-only');
select pg_temp.expect_error($q$select public.record_test_consent('10000000-0000-0000-0000-000000000001',(select event from consent_intent),false,'Stale consent must not override a new event.',gen_random_uuid())$q$,'40001','stale consent denied');
select public.record_test_consent('10000000-0000-0000-0000-000000000001',(public.load_test_trust_workspace()#>>'{relationships,0,consent_event}')::bigint,false,'Adult test consent is explicitly withdrawn.',gen_random_uuid());
select pg_temp.assert_true((select count(*)=0 from public.lesson_progress),'withdrawal immediately removes new private reads');
select pg_temp.expect_error($q$select public.read_linked_test_learner('10000000-0000-0000-0000-000000000001')$q$,'42501','withdrawn linked read denied');
select pg_temp.assert_true(public.load_test_trust_history('consent','10000000-0000-0000-0000-000000000001')#>>'{records,0,status}'='revoked','latest immutable consent is authoritative');
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000007","session_id":"00000000-0000-0000-0000-000000000007"}',true);
select pg_temp.expect_error($q$select public.load_test_trust_history('consent','10000000-0000-0000-0000-000000000001')$q$,'42501','unrelated guardian cannot inspect consent history');
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000001","session_id":"00000000-0000-0000-0000-000000000001"}',true);
select pg_temp.assert_true(private.account_session_active(),'learner session active before report');
select pg_temp.assert_true((select count(*)=1 from public.user_roles where role='learner'),'learner role visible before report');
create temporary table submitted_report as select public.submit_test_safety_report('83000000-0000-4000-8000-000000000001','content','Synthetic adult classroom report; no real incident.') id;
select pg_temp.assert_true(public.submit_test_safety_report('83000000-0000-4000-8000-000000000001','content','Synthetic adult classroom report; no real incident.')=(select id from submitted_report),'duplicate submissions return same server report ID');
select pg_temp.assert_true((select id<>'83000000-0000-4000-8000-000000000001' from submitted_report),'report identifier generated by server');
select pg_temp.expect_error($q$select public.submit_test_safety_report('83000000-0000-4000-8000-000000000001','content','Altered summary must not reuse a submission token.')$q$,'22023','changed duplicate payload rejected');
select pg_temp.expect_error($q$select * from public.test_safety_actions$q$,'42501','reporter cannot read private review evidence');
select pg_temp.expect_error($q$select public.review_test_safety_report((select id from submitted_report),1,'resolved','Unauthorised review cannot be recorded.',gen_random_uuid())$q$,'42501','reporter cannot resolve report');
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000002","session_id":"00000000-0000-0000-0000-000000000002"}',true);
select pg_temp.assert_true((select count(*)=0 from public.test_safety_reports),'report cross-account isolation');
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000005","session_id":"00000000-0000-0000-0000-000000000005"}',true);
select pg_temp.expect_error($q$select public.review_test_safety_report((select id from submitted_report),1,'resolved','Cannot skip the under-review state.',gen_random_uuid())$q$,'22023','invalid transition denied');
select public.review_test_safety_report((select id from submitted_report),1,'under_review','Synthetic test report accepted for independent review.',gen_random_uuid());
select pg_temp.expect_error($q$select public.review_test_safety_report((select id from submitted_report),1,'closed','Stale reviewer cannot overwrite current work.',gen_random_uuid())$q$,'40001','stale safety update denied');
select public.review_test_safety_report((select id from submitted_report),2,'resolved','Synthetic issue resolved; private operator note.','84000000-0000-4000-8000-000000000001');
select public.review_test_safety_report((select id from submitted_report),2,'resolved','Synthetic issue resolved; private operator note.','84000000-0000-4000-8000-000000000001');
select pg_temp.assert_true(jsonb_array_length(public.load_test_trust_history('safety',(select id from submitted_report))->'records')=3,'one action per committed state change');
select pg_temp.expect_error($q$select public.review_test_safety_report((select id from submitted_report),3,'under_review','Terminal reports cannot be reopened.',gen_random_uuid())$q$,'22023','terminal state immutable through client transitions');
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000001","session_id":"00000000-0000-0000-0000-000000000001"}',true);
select pg_temp.assert_true(public.load_test_trust_workspace()#>>'{reports,0,status}'='resolved','reporter sees actual status');
select pg_temp.assert_true(public.load_test_trust_workspace()::text not like '%private operator note%','reporter projection excludes review evidence');
select pg_temp.expect_error($q$select public.load_test_trust_history('safety',(select id from submitted_report))$q$,'42501','reporter cannot request private action history');
reset role;
update auth.users set banned_until=now()+interval '1 hour' where id='00000000-0000-0000-0000-000000000001';
set local role authenticated;
select pg_temp.expect_error($q$select public.submit_test_safety_report(gen_random_uuid(),'content','Banned account may not submit reports.')$q$,'42501','banned session denied');
reset role;
